const supported_languages = ['en', 'fr', 'de', 'es', 'it', 'pt', 'nl', 'pl'];
const stored_language = localStorage.getItem('ai_interview_language');
const browser_language = navigator.language.split('-')[0];
const initial_language = stored_language && supported_languages.includes(stored_language) ? stored_language : supported_languages.includes(browser_language) ? browser_language : 'en';

i18n.use(initReactI18next).init({resources, lng: initial_language, fallbackLng: 'en', interpolation: {escapeValue: false}});

i18n.on('languageChanged', (language) => {
    const normalized = language.split('-')[0];
    localStorage.setItem('ai_interview_language', normalized);
    document.documentElement.lang = normalized;
    document.cookie = `django_language=${encodeURIComponent(normalized)}; Path=/; SameSite=Lax`;
});

document.documentElement.lang = initial_language;

export default i18n;
